parameters.jsonBody:
={{ JSON.stringify({ 
  model: "llama-3.3-70b-versatile", 
  messages: [{ 
    role: "user", 
    content: 
    "Analyze this GitHub issue. " +
    "Title: " + $json.title + 
    ". Description: " + $json.description + 
    ". Choose exactly one category from: Bug, Feature, Technical, Documentation, UI/UX, Performance, Security, Question. " +
    "Choose priority from: Low, Medium, High, Critical. " +
    "Return only JSON in this format: " +
    '{"category":"","priority":"","comment":""}'
  }] 
}) }}
